"""
VoxPilot - Agent Execution State Model
Defines the shared typed state dictionary exchanged between LangGraph nodes
throughout intent recognition, planning, validation, execution, and evaluation.
"""

from typing import Any, Optional, List, Dict
from typing_extensions import TypedDict


class PlanStep(TypedDict, total=False):
    """Structured plan step generated by the planner."""
    action: str
    description: str
    parameters: Dict[str, Any]
    requires_confirmation: bool


class ExecutionResult(TypedDict, total=False):
    """Structured result recorded after executing a single tool step."""
    step_index: int
    action: str
    success: bool
    status: str
    message: str
    data: Optional[Dict[str, Any]]
    error: Optional[str]
    confirmation_token: Optional[str]


class PendingConfirmation(TypedDict, total=False):
    """Structured metadata for an action paused awaiting human user confirmation."""
    token: str
    action: str
    parameters: Dict[str, Any]
    description: str
    execution_id: str
    step_index: int


class VoxPilotState(TypedDict, total=False):
    """Shared state dictionary passed between VoxPilot agent LangGraph nodes.

    Attributes:
        user_input: Original natural language request from user or voice pipeline.
        intent: Classified intent category.
        confidence: Intent classification confidence score (0.0 to 1.0).
        intent_reason: Natural language justification for the classified intent.
        plan: Ordered list of validated plan step objects to execute.
        current_step: 0-based index of the step currently being executed or evaluated.
        current_action: The exact step dictionary currently being executed.
        execution_results: Chronological log of execution result objects for executed steps.
        completed_steps: List of steps that succeeded.
        failed_steps: List of steps that failed.
        execution_status: Current execution lifecycle state:
            'started', 'planned', 'validated', 'validation_failed',
            'running', 'completed', 'failed', 'confirmation_required', 'cancelled'.
        response: Final natural language response presented or spoken to user.
        error: Detailed error message if planning, validation, or execution failed.
        requires_confirmation: Boolean indicating if any step requires human approval.
        pending_confirmation: Metadata describing an active paused confirmation request.
        execution_id: Unique string identifier tracking this execution session.
    """
    user_input: str
    intent: str
    confidence: float
    intent_reason: str
    plan: List[Dict[str, Any]]
    current_step: int
    current_action: Optional[Dict[str, Any]]
    current_execution_result: Optional[Dict[str, Any]]
    execution_results: List[Dict[str, Any]]
    completed_steps: List[Dict[str, Any]]
    failed_steps: List[Dict[str, Any]]
    execution_status: str
    response: str
    error: str
    requires_confirmation: bool
    pending_confirmation: Optional[Dict[str, Any]]
    execution_id: str
    conversation_id: str
    conversation_history: Optional[str]
    replan_count: int
    max_replans: int
    needs_replan: bool
    replan_reason: Optional[str]
    replan_history: List[Dict[str, Any]]
    started_at: Optional[float]
